INSERT INTO emr_template (
    id, name, code, document_type_code, scope_level, encounter_class_code,
    content, is_enabled, created_at, is_deleted, tenant_id, created_by
) VALUES
(
    323100000000000207,
    '患者入院安全告知书',
    'IP_ADMISSION_SAFETY',
    'NOTICE',
    'HOSPITAL',
    'IMP',
    $tpl_admission_safety$
{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":"center","name":"hospitalTitle"},"content":[{"type":"emrDataElement","attrs":{"elementId":"orgName","labelSnapshot":"机构名称","value":"","placeholder":"机构名称","widgetOverride":"text","optionsJson":"[]","editable":false}}]},{"type":"paragraph","content":[{"type":"text","text":"患者入院安全告知书","marks":[{"type":"bold"}]}],"attrs":{"textAlign":"center","name":"formTitle"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"尊敬的患者及家属，我院认真贯彻“预防为主、防治结合、综合治理”安全生产工作方针，为避免安全生产、治安消防事故发生，特将相关安全事项内容告知如下："}],"attrs":{"textAlign":"justify","name":"noticeIntro"}},{"type":"paragraph","content":[{"type":"text","text":"一、住院期间严禁吸烟、动用明火、私接电线及插排。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"二、病房内严禁使用大功率电器，如：电热杯、酒精炉等，以免发生火灾，充电设备不使用时要及时拔除。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"三、严禁损坏、挪用、遮挡消防设施和器材。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"四、知晓安全出口和疏散通道位置，如遇火灾，请听从工作人员统一指挥，迅速从安全出口撤离，不要乘坐电梯，并拨打119报警电话。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"五、院区内车辆有序停放，禁止占用消防车道。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"六、电动车（含便携式电动车电池）禁止进入室内充电。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"七、病人输氧时，严禁使用明火，不得用有油污的手和抹布触摸制氧设备；氧气如有泄漏请及时告诉医护人员处理。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"八、严禁高空抛物；严禁点燃蚊香；严禁攀爬窗户和阳台；严禁携带易燃易爆品、危险品、管制刀具进入医院。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"九、请妥善保管好您的贵重物品和现金，以免丢失，不要随意委托他人看管。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"十、灭火器使用方法：将安全销拉开将皮管朝向火点、用力压下把手，选择上风位置接近火点，将干粉射入火焰。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"paragraph","content":[{"type":"text","text":"十一、逃生面具使用方法：打开盒盖，取出并撕开真空包装袋，拔掉前后两个灌塞，戴上头套，拉紧头带。"}],"attrs":{"textAlign":"justify","name":"noticeItem"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"以上内容本人已知晓，表示理解并确认。"}],"attrs":{"textAlign":"justify","name":"noticeConfirm"}},{"type":"table","attrs":{"name":"admissionSafetySign"},"content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignLeft"},"content":[{"type":"paragraph","content":[{"type":"text","text":"本人或家属签字："},{"type":"emrDataElement","attrs":{"elementId":"familySigner","labelSnapshot":"本人或家属签字","value":"","placeholder":"本人或家属签字","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"＿＿＿＿＿＿＿＿"}],"attrs":{"name":"noticeSignLeft"}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignRight"},"content":[{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"signDate","labelSnapshot":"签署日期","value":"","placeholder":"签署日期","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"textAlign":"right","name":"noticeSignRight"}}]}]}]}]}
