    323100000000000211,
    '尸体解剖告知书',
    'IP_AUTOPSY_NOTICE',
    'NOTICE',
    'HOSPITAL',
    'IMP',
    $tpl_autopsy$
{"type":"doc","content":[{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"orgName","labelSnapshot":"机构名称","value":"","placeholder":"机构名称","widgetOverride":"text","optionsJson":"[]","editable":false}}],"attrs":{"name":"hospitalTitle","textAlign":"center"}},{"type":"paragraph","content":[{"type":"text","text":"尸体解剖告知书","marks":[{"type":"bold"}]}],"attrs":{"name":"formTitle","textAlign":"center"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"患者姓名："},{"type":"emrDataElement","attrs":{"elementId":"patientName","labelSnapshot":"患者姓名","value":"","placeholder":"患者姓名","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　性别："},{"type":"emrDataElement","attrs":{"elementId":"gender","labelSnapshot":"性别","value":"","placeholder":"性别","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　年龄："},{"type":"emrDataElement","attrs":{"elementId":"age","labelSnapshot":"年龄","value":"","placeholder":"年龄","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　科室："},{"type":"emrDataElement","attrs":{"elementId":"deptName","labelSnapshot":"科室","value":"","placeholder":"科室","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　病历号："},{"type":"emrDataElement","attrs":{"elementId":"medicalRecordNo","labelSnapshot":"病历号","value":"","placeholder":"病历号","widgetOverride":"text","optionsJson":"[]","editable":false}}],"attrs":{"name":"riskPatientInfo"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"医方告知","marks":[{"type":"bold"}]}],"attrs":{"name":"riskSectionTitle"}},{"type":"paragraph","content":[{"type":"text","text":"尊敬的患者家属或患者的法定监护人、授权委托人：您的家人"},{"type":"emrDataElement","attrs":{"elementId":"patientName","labelSnapshot":"死者姓名","value":"","placeholder":"死者姓名","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"在我院"},{"type":"emrDataElement","attrs":{"elementId":"deptName","labelSnapshot":"科室","value":"","placeholder":"科室","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"科住院治疗，因疾病"},{"type":"emrDataElement","attrs":{"elementId":"deathCause","labelSnapshot":"疾病/死因","value":"","placeholder":"疾病/死因","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"于"},{"type":"emrDataElement","attrs":{"elementId":"deathAt","labelSnapshot":"死亡时间","value":"","placeholder":"死亡时间","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"去世，敬请节哀并特此告知如下事项："}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"1、如死者生前未对尸体作出明确处理意见，死者的家属具有对尸体及器官捐献的处置权。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"2、如家属对死者的死因有异议，应在48小时内提出尸检申请。我院具有尸体冷冻条件，尸检时间可以延长至7日（尸体冷冻费用需另行交纳）。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"3、如因拒绝或者拖延尸检，超过规定时间，从而对死因判定的产生了影响，自行承担责任。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"4、尸体解剖的过程需要损坏死者的体貌，取出必要的组织、内脏器官进行检验，所以在尸体解剖时尸体的体貌会有所损坏，同时死者的部分组织、内脏器官会缺失。并且即使进行了全面、系统的尸体解剖和病理检验，仍有可能查不出真正的死因。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"5、尸检需要在以下具备资格的机构进行：（1）卫生行政部门批准设置具有独立病理解剖能力病理科的医疗机构；（2）设有具备独立病理解剖能力的病理教研室或法医教研室的医学院校，或设有医学专业的并具备独立病理解剖能力的病理教研室或法医教研室的高等普通学校；（3）医患双方可共同选择经过国家司法行政部门批准的司法鉴定机构；"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"6、您可以委托法医病理学人员参加尸检，也可以委派代表观察尸检过程。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"患方意见","marks":[{"type":"bold"}]}],"attrs":{"name":"riskSectionTitle"}},{"type":"paragraph","content":[{"type":"text","text":"医护人员已经将尸检的相关情况向我做了详细的说明，并且及时解答了相关问题。经慎重考虑，我们对尸检处理的决定是："},{"type":"emrDataElement","attrs":{"elementId":"autopsyDecision","labelSnapshot":"同意尸检/不同意尸检","value":"","placeholder":"同意尸检/不同意尸检","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"（填「同意尸检」或「不同意尸检」）。"}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"死者授权亲属签名："},{"type":"emrDataElement","attrs":{"elementId":"guardianSigner","labelSnapshot":"死者授权亲属签名","value":"","placeholder":"死者授权亲属签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　与死者关系："},{"type":"emrDataElement","attrs":{"elementId":"patientRelation","labelSnapshot":"与死者关系","value":"","placeholder":"与死者关系","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　签名日期："},{"type":"emrDataElement","attrs":{"elementId":"signDate","labelSnapshot":"签名日期","value":"","placeholder":"签名日期","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"riskGuardianSign"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"医护人员陈述","marks":[{"type":"bold"}]}],"attrs":{"name":"riskSectionTitle"}},{"type":"paragraph","content":[{"type":"text","text":"我已经将尸检的相关情况向患者家属或患者的法定监护人、授权委托人做了详细的告知，并且解答了相关问题。"}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"table","attrs":{"name":"admissionSafetySign"},"content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignLeft"},"content":[{"type":"paragraph","content":[{"type":"text","text":"医护人员签名："},{"type":"emrDataElement","attrs":{"elementId":"recorderName","labelSnapshot":"医护人员签名","value":"","placeholder":"医护人员签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"＿＿＿＿＿＿"}],"attrs":{"name":"noticeSignLeft"}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignRight"},"content":[{"type":"paragraph","content":[{"type":"text","text":"签名日期："},{"type":"emrDataElement","attrs":{"elementId":"staffSignAt","labelSnapshot":"签名日期","value":"","placeholder":"签名日期","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeSignRight","textAlign":"right"}}]}]}]}]}
