(
    323100000000000212,
    '使用人血白蛋白知情同意书',
    'IP_ALBUMIN_CONSENT',
    'NOTICE',
    'HOSPITAL',
    'IMP',
    $tpl_albumin$
{"type":"doc","content":[{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"orgName","labelSnapshot":"机构名称","value":"","placeholder":"机构名称","widgetOverride":"text","optionsJson":"[]","editable":false}}],"attrs":{"name":"hospitalTitle","textAlign":"center"}},{"type":"paragraph","content":[{"type":"text","text":"使用人血白蛋白知情同意书","marks":[{"type":"bold"}]}],"attrs":{"name":"formTitle","textAlign":"center"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"科室："},{"type":"emrDataElement","attrs":{"elementId":"deptName","labelSnapshot":"科室","value":"","placeholder":"科室","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　姓名："},{"type":"emrDataElement","attrs":{"elementId":"patientName","labelSnapshot":"患者姓名","value":"","placeholder":"患者姓名","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　床号："},{"type":"emrDataElement","attrs":{"elementId":"bedNo","labelSnapshot":"床号","value":"","placeholder":"床号","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　住院号："},{"type":"emrDataElement","attrs":{"elementId":"inpatientNo","labelSnapshot":"住院号","value":"","placeholder":"住院号","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　签署时间："},{"type":"emrDataElement","attrs":{"elementId":"signDate","labelSnapshot":"签署时间","value":"","placeholder":"签署时间","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"riskPatientInfo"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"（一）患者因病情需要使用人血白蛋白。药物来源（填「院内」或「自购」）："}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"albuminSource","labelSnapshot":"药物来源","value":"","placeholder":"药物来源","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeIntro"}},{"type":"paragraph","content":[{"type":"text","text":"（二）使用目的：支持治疗"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"（三）使用人血白蛋白过程中及使用后可能出现的风险、并发症和意外情况："}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"1.静脉用人血白蛋白属于血液制品，存在感染血源性传染性疾病，如艾滋病、梅毒、肝炎（乙肝、丙肝等）、巨细胞病毒或EB病毒、疟疾等。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"2.不良反应如过敏反应、发热反应，偶可出现寒颤、颜面潮红、皮疹、恶心呕吐等症状；循环超负荷；心脑血管意外；其他一些不可预知的意外、风险。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"3.输血液制品引起的其他疾病。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"4.其它难以预料的意外情况。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"5.自购药品的安全性、有效性不能保证。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"6.如出现上述意外情况，可能导致实际费用较预计费用明显增加，医保病人可能使用非医保药物或材料，需要病人自付。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"（四）被告知人对上述内容已完全知晓并表示理解，且做如下表态（填「同意使用」或「不同意使用」）："}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"consentChoice","labelSnapshot":"同意/不同意使用","value":"","placeholder":"同意/不同意使用","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeIntro"}},{"type":"paragraph","content":[{"type":"text","text":"患者签名："},{"type":"emrDataElement","attrs":{"elementId":"patientSigner","labelSnapshot":"患者签名","value":"","placeholder":"患者签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　家属签名："},{"type":"emrDataElement","attrs":{"elementId":"familySigner","labelSnapshot":"家属签名","value":"","placeholder":"家属签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　与患者关系："},{"type":"emrDataElement","attrs":{"elementId":"patientRelation","labelSnapshot":"与患者关系","value":"","placeholder":"与患者关系","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"riskGuardianSign"}},{"type":"table","attrs":{"name":"admissionSafetySign"},"content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignLeft"},"content":[{"type":"paragraph","content":[{"type":"text","text":"医师签名："},{"type":"emrDataElement","attrs":{"elementId":"recorderName","labelSnapshot":"医师签名","value":"","placeholder":"医师签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"＿＿＿＿＿＿"}],"attrs":{"name":"noticeSignLeft"}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignRight"},"content":[{"type":"paragraph","content":[{"type":"text","text":"签署时间："},{"type":"emrDataElement","attrs":{"elementId":"staffSignAt","labelSnapshot":"签署时间","value":"","placeholder":"签署时间","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeSignRight","textAlign":"right"}}]}]}]}]}
