    $tpl_ext_drug$
{"type":"doc","content":[{"type":"paragraph","content":[{"type":"emrDataElement","attrs":{"elementId":"orgName","labelSnapshot":"机构名称","value":"","placeholder":"机构名称","widgetOverride":"text","optionsJson":"[]","editable":false}}],"attrs":{"name":"hospitalTitle","textAlign":"center"}},{"type":"paragraph","content":[{"type":"text","text":"使用外购药品知情同意书","marks":[{"type":"bold"}]}],"attrs":{"name":"formTitle","textAlign":"center"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"患者姓名："},{"type":"emrDataElement","attrs":{"elementId":"patientName","labelSnapshot":"患者姓名","value":"","placeholder":"患者姓名","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　性别："},{"type":"emrDataElement","attrs":{"elementId":"gender","labelSnapshot":"性别","value":"","placeholder":"性别","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　年龄："},{"type":"emrDataElement","attrs":{"elementId":"age","labelSnapshot":"年龄","value":"","placeholder":"年龄","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　联系方式："},{"type":"emrDataElement","attrs":{"elementId":"phone","labelSnapshot":"联系方式","value":"","placeholder":"联系方式","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"riskPatientInfo"}},{"type":"paragraph","content":[{"type":"text","text":"科室："},{"type":"emrDataElement","attrs":{"elementId":"deptName","labelSnapshot":"科室","value":"","placeholder":"科室","widgetOverride":"text","optionsJson":"[]","editable":false}},{"type":"text","text":"　　床号："},{"type":"emrDataElement","attrs":{"elementId":"bedNo","labelSnapshot":"床号","value":"","placeholder":"床号","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　住院号/门诊号："},{"type":"emrDataElement","attrs":{"elementId":"inpatientNo","labelSnapshot":"住院号/门诊号","value":"","placeholder":"住院号/门诊号","widgetOverride":"text","optionsJson":"[]","editable":false}}],"attrs":{"name":"riskPatientInfo"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"因疾病治疗的需要考虑使用外购药品。但使用该药物可能发生不良反应、难以避免的用药意外、并发症或其他风险(包括但不限于)："}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"1.因患者个体差异等特殊情况对药物发生过敏、中毒等不良反应而产生的损害；相关的药物不良反应和其他难以预料的意外或并发症。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"2.非本院采购药品，质量来源不能完全确保。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"3.外购药品疗效可能不能达到预期。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"4.增加医保费用外的自费费用负担。"}],"attrs":{"name":"noticeItem","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"外购药品必须从正规的医疗机构或正规的药店购买，已提醒索要和留存有效购销凭证，因外购药品价格不统一可能导致药费增加。医师没有指定外购药品的药店(含与医疗机构有直接或间接关系的自费药房、自办药店、便民药店等)或其他医疗机构的同类药房。"}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"horizontalRule","attrs":{"lineColor":"#000000","lineWidth":1}},{"type":"paragraph","content":[{"type":"text","text":"经过医生告知，本人已充分理解上述谈话内容的含义。经慎重考虑，本人对使用外购药品可能出现的风险表示充分理解，并相信医护人员将竭尽全力救治。由于病情需要，本人同意并授权医院使用外购药物并愿意承担由此产生的一切风险，签字为证。"}],"attrs":{"name":"noticeIntro","textAlign":"justify"}},{"type":"paragraph","content":[{"type":"text","text":"患者签名："},{"type":"emrDataElement","attrs":{"elementId":"patientSigner","labelSnapshot":"患者签名","value":"","placeholder":"患者签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　家属签名："},{"type":"emrDataElement","attrs":{"elementId":"familySigner","labelSnapshot":"家属签名","value":"","placeholder":"家属签名","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　　与患者关系："},{"type":"emrDataElement","attrs":{"elementId":"patientRelation","labelSnapshot":"与患者关系","value":"","placeholder":"与患者关系","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"riskGuardianSign"}},{"type":"table","attrs":{"name":"admissionSafetySign"},"content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignLeft"},"content":[{"type":"paragraph","content":[{"type":"text","text":"签字日期："},{"type":"emrDataElement","attrs":{"elementId":"signDate","labelSnapshot":"签字日期","value":"","placeholder":"签字日期","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeSignLeft"}}]},{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"name":"noticeSignRight"},"content":[{"type":"paragraph","content":[{"type":"text","text":"医护签字："},{"type":"emrDataElement","attrs":{"elementId":"recorderName","labelSnapshot":"医护签字","value":"","placeholder":"医护签字","widgetOverride":"text","optionsJson":"[]","editable":true}},{"type":"text","text":"　"},{"type":"emrDataElement","attrs":{"elementId":"staffSignAt","labelSnapshot":"签字时间","value":"","placeholder":"签字时间","widgetOverride":"text","optionsJson":"[]","editable":true}}],"attrs":{"name":"noticeSignRight","textAlign":"right"}}]}]}]}]}
